<script setup lang="ts">
import { computed, nextTick, reactive, ref, watch } from 'vue'
import { loadQuotationUser } from '@/utils/quotationSession'
import { loadQuotationRecords, updateQuotationRecord, type QuotationRecord, type QuotationRecordDealLine, type QuotationRecordQuoteOption, type QuotationRecordStatus } from '@/data/quotationRecords'
import { loadPurchaseProducts } from '@/data/purchaseStore'
import { quotationProductCategories } from '@/components/quotation/types'

const props = defineProps<{ scope: 'mine' | 'company' }>()
const user = loadQuotationUser()
const records = ref(loadQuotationRecords())
const purchaseProducts = loadPurchaseProducts()
const search = ref('')
const filterStatus = ref<'' | QuotationRecordStatus>('')
const filterCountry = ref('')
const filterCategory = ref('')
const selected = ref<QuotationRecord | null>(null)
const editing = ref(false)
const detailTab = ref<'overview' | 'options' | 'history'>('overview')
const notice = ref('')
const dealLineEditor = ref<HTMLElement | null>(null)
interface DealLineForm { id: string; optionId: string; unitPriceUsd: string; quantity: string }
const form = reactive({ status: 'won' as 'won' | 'lost', dealLines: [] as DealLineForm[], date: new Date().toISOString().slice(0, 10), note: '' })
const isMine = computed(() => props.scope === 'mine')
const title = computed(() => isMine.value ? '我的报价记录' : '公司报价记录')
const scoped = computed(() => isMine.value ? records.value.filter(item => item.salespersonName === user.name && item.salespersonAccount === user.account) : records.value)
function recordOptions(row: QuotationRecord) { return row.quoteOptions || [] }
function optionLabel(option: QuotationRecordQuoteOption) { return `${option.country}${option.quoteRegion ? `（${option.quoteRegion}）` : ''} · ${option.channel}${option.carrier && option.carrier !== option.channel ? ` · ${option.carrier}` : ''}` }
function recordCountries(row: QuotationRecord) { return [...new Set(recordOptions(row).map(option => option.country).filter(country => country && country !== '—'))] }
function hasMultipleOptions(row: QuotationRecord) { return recordOptions(row).length > 1 }
function primaryOption(row: QuotationRecord) { return recordOptions(row).find(option => option.isPrimary) || recordOptions(row)[0] }
function numericRange(values: number[], prefix = '') {
  const sorted = [...new Set(values.filter(Number.isFinite))].sort((a, b) => a - b)
  if (!sorted.length) return '—'
  const first = `${prefix}${sorted[0].toFixed(2)}`
  return sorted.length === 1 ? first : `${first} ~ ${prefix}${sorted[sorted.length - 1].toFixed(2)}`
}
function quote1UsdRange(row: QuotationRecord) { return numericRange(recordOptions(row).flatMap(option => option.quote1Usd == null ? [] : [option.quote1Usd]), '$') }
function quote1CnyRange(row: QuotationRecord) { return numericRange(recordOptions(row).flatMap(option => option.quote1Usd == null ? [] : [option.quote1Usd * row.exchangeRate]), '¥') }
function optionPrice(value: number | null) { return value == null ? '—' : usd(value) }
const countries = computed(() => [...new Set(scoped.value.flatMap(item => [item.country, ...recordCountries(item)]).filter(country => country && country !== '—'))].sort((a, b) => a.localeCompare(b, 'zh-CN')))
const list = computed(() => scoped.value.filter(item => {
  const quoteKey = recordOptions(item).flatMap(quote => [quote.country, quote.carrier, quote.channel, quote.rule]).join(' ')
  const key = [item.no, item.customerName, item.primarySku, item.productCategory, item.country, item.carrier, item.channel, item.salespersonName, quoteKey].join(' ').toLowerCase()
  const matchesCountry = !filterCountry.value || item.country === filterCountry.value || recordOptions(item).some(quote => quote.country === filterCountry.value)
  return (!search.value.trim() || key.includes(search.value.trim().toLowerCase())) && (!filterStatus.value || item.status === filterStatus.value) && matchesCountry && (!filterCategory.value || item.productCategory === filterCategory.value)
}))
const revisionGroups = computed(() => {
  const groups = new Map<string, { id: string; changedAt: string; editorName: string; editorAccount: string; changes: QuotationRecord['revisions'] }>()
  for (const revision of selected.value?.revisions || []) {
    const key = `${revision.changedAt}-${revision.editorAccount}`
    const group = groups.get(key)
    if (group) group.changes.push(revision)
    else groups.set(key, { id: key, changedAt: revision.changedAt, editorName: revision.editorName, editorAccount: revision.editorAccount, changes: [revision] })
  }
  return [...groups.values()].reverse()
})
const selectedOptionGroups = computed(() => {
  const groups = new Map<string, { country: string; countryCode?: string; options: QuotationRecordQuoteOption[] }>()
  for (const option of selected.value ? recordOptions(selected.value) : []) {
    const group = groups.get(option.country)
    if (group) group.options.push(option)
    else groups.set(option.country, { country: option.country, countryCode: option.countryCode, options: [option] })
  }
  return [...groups.values()]
})
const selectedDealOptionIds = computed(() => new Set((selected.value?.dealLines || []).map(line => line.optionId)))
const formDealTotalQuantity = computed(() => form.dealLines.reduce((sum, line) => sum + (Number(line.quantity) || 0), 0))
const formDealTotalUsd = computed(() => form.dealLines.reduce((sum, line) => sum + (Number(line.unitPriceUsd) || 0) * (Number(line.quantity) || 0), 0))
const pending = computed(() => scoped.value.filter(item => item.status === 'pending').length)
const won = computed(() => scoped.value.filter(item => item.status === 'won').length)
const lost = computed(() => scoped.value.filter(item => item.status === 'lost').length)
const cny = (value: number) => `¥${value.toFixed(2)}`
const usd = (value: number) => `$${value.toFixed(2)}`
const statusText = (value: QuotationRecordStatus) => ({ pending: '待处理', won: '已成交', lost: '未成交' })[value]
const dateTime = (value?: string) => {
  if (!value) return '—'
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(date)
}
function recordProductImage(row: QuotationRecord) {
  if (row.productImage) return row.productImage
  const primarySku = row.primarySku.split(/[、,+\s]/).find(Boolean) || row.primarySku
  return purchaseProducts.find(item => item.sku === primarySku)?.image || ''
}
function fillForm(row: QuotationRecord) {
  form.status = row.status === 'lost' ? 'lost' : 'won'
  form.dealLines = (row.dealLines || []).map(line => ({ id: line.id, optionId: line.optionId, unitPriceUsd: line.unitPriceUsd.toFixed(2), quantity: String(line.quantity) }))
  if (!form.dealLines.length && recordOptions(row).length === 1) form.dealLines.push({ id: `draft-${Date.now()}`, optionId: recordOptions(row)[0].id, unitPriceUsd: '', quantity: '' })
  form.date = row.closedAt || new Date().toISOString().slice(0, 10)
  form.note = row.note || ''
}
async function addDealLine() {
  if (!selected.value) return
  const used = new Set(form.dealLines.map(line => line.optionId))
  const option = recordOptions(selected.value).find(item => !used.has(item.id))
  if (!option) { toast('报价单中的渠道已经全部添加'); return }
  form.dealLines.push({ id: `draft-${Date.now()}-${form.dealLines.length}`, optionId: option.id, unitPriceUsd: '', quantity: '' })
  await nextTick()
  dealLineEditor.value?.querySelector('article:last-of-type')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
}
function removeDealLine(index: number) { form.dealLines.splice(index, 1) }
function availableDealOptions(line: DealLineForm) {
  if (!selected.value) return []
  const used = new Set(form.dealLines.filter(item => item !== line).map(item => item.optionId))
  return recordOptions(selected.value).filter(option => option.id === line.optionId || !used.has(option.id))
}
function open(row: QuotationRecord) {
  selected.value = row
  detailTab.value = 'overview'
  editing.value = false
  fillForm(row)
}
function processRecord(row: QuotationRecord) {
  selected.value = row
  fillForm(row)
  editing.value = isMine.value
}
function closeDrawer() { editing.value = false; selected.value = null }
function cancelEdit() {
  if (!selected.value) return
  fillForm(selected.value)
  editing.value = false
}
function submit() {
  if (!selected.value) return
  const options = recordOptions(selected.value)
  if (form.status === 'won' && !form.dealLines.length) { toast('请至少添加一条成交方案'); return }
  const dealLines: QuotationRecordDealLine[] = []
  for (const [index, line] of form.dealLines.entries()) {
    const option = options.find(item => item.id === line.optionId)
    const unitPriceUsd = Number(line.unitPriceUsd)
    const quantity = Number(line.quantity)
    if (!option) { toast(`请选择第 ${index + 1} 条成交方案的国家和物流渠道`); return }
    if (!(unitPriceUsd > 0)) { toast(`请填写第 ${index + 1} 条成交方案的有效成交单价`); return }
    if (!Number.isInteger(quantity) || quantity <= 0) { toast(`请填写第 ${index + 1} 条成交方案的正整数成交数量`); return }
    dealLines.push({ id: line.id.startsWith('draft-') ? `deal-${Date.now()}-${index}` : line.id, optionId: option.id, optionLabel: optionLabel(option), country: option.country, carrier: option.carrier, channel: option.channel, unitPriceUsd, quantity, amountUsd: Number((unitPriceUsd * quantity).toFixed(2)) })
  }
  if (!form.date) { toast('请选择处理日期'); return }
  const previousUpdatedAt = selected.value.updatedAt
  const savedLines = form.status === 'won' ? dealLines : []
  const totalUsd = savedLines.reduce((sum, line) => sum + line.amountUsd, 0)
  const totalQuantity = savedLines.reduce((sum, line) => sum + line.quantity, 0)
  const singleLine = savedLines.length === 1 ? savedLines[0] : undefined
  const updated = updateQuotationRecord(selected.value.id, { status: form.status, dealLines: savedLines, dealOptionId: singleLine?.optionId, dealOptionLabel: singleLine?.optionLabel || (savedLines.length ? `${savedLines.length}条成交方案` : undefined), actualQuoteUsd: savedLines.length ? totalUsd : undefined, actualQuoteCny: savedLines.length ? totalUsd * selected.value.exchangeRate : undefined, dealQuantity: savedLines.length ? totalQuantity : undefined, closedAt: form.date, note: form.note.trim() || undefined }, { name: user.name, account: user.account })
  if (!updated) { toast('保存失败，请刷新页面后重试'); return }
  records.value = loadQuotationRecords(); selected.value = records.value.find(item => item.id === selected.value?.id) || null
  editing.value = false
  toast(updated.updatedAt === previousUpdatedAt ? '没有检测到内容变化' : '报价结果已保存，并记录本次修改时间')
}
function toast(text: string) { notice.value = text; window.setTimeout(() => notice.value === text && (notice.value = ''), 2400) }
watch(list, rows => {
  if (selected.value && !rows.some(row => row.id === selected.value?.id)) closeDrawer()
})
</script>

<template>
  <div class="app">
    <header class="topbar"><RouterLink class="brand" to="/quotation"><i>M</i><span><b>米莱诺报价</b><small>MILANO PRICING ERP</small></span></RouterLink><nav><RouterLink to="/quotation">业务报价</RouterLink><RouterLink to="/quotation/products">采购资料</RouterLink><RouterLink to="/quotation/logistics">物流规则</RouterLink><RouterLink to="/quotation/members">财务设置</RouterLink><RouterLink :class="{active:isMine}" to="/quotation/my-records">我的报价记录</RouterLink><RouterLink :class="{active:!isMine}" to="/quotation/records">公司报价记录</RouterLink></nav><div class="user"><i>{{ user.name.slice(0,2) }}</i><span><b>{{ user.name }}</b><small>{{ user.account }}</small></span></div></header>
    <main><header class="heading"><div><p>QUOTATION FOLLOW-UP</p><h1>{{ title }}</h1><span>{{ isMine ? '跟进本人系统报价与客户实际成交结果' : '查看全体业务员的报价与成交回填记录' }}</span></div><RouterLink v-if="isMine" to="/quotation">＋ 新建报价</RouterLink></header>
      <section class="stats"><article class="red"><i>!</i><span><small>待处理</small><b>{{ pending }}</b><em>需要回填成交结果</em></span></article><article class="green"><i>✓</i><span><small>已成交</small><b>{{ won }}</b><em>已完成真实报价回填</em></span></article><article><i>×</i><span><small>未成交</small><b>{{ lost }}</b><em>已确认但没有成交</em></span></article><article><i>总</i><span><small>全部报价</small><b>{{ scoped.length }}</b><em>保留系统报价快照</em></span></article></section>
      <section class="filters"><label class="search">⌕<input v-model="search" placeholder="搜索客户、SKU、品类、国家、渠道或报价单号"></label><label>状态<select v-model="filterStatus"><option value="">全部状态</option><option value="pending">待处理</option><option value="won">已成交</option><option value="lost">未成交</option></select></label><label>产品品类<select v-model="filterCategory"><option value="">全部品类</option><option v-for="item in quotationProductCategories" :key="item" :value="item">{{ item }}</option></select></label><label>报价国家<select v-model="filterCountry"><option value="">全部国家</option><option v-for="item in countries" :key="item">{{ item }}</option></select></label><button @click="search='';filterStatus='';filterCategory='';filterCountry=''">重置</button><b>共 {{ list.length }} 条记录</b></section>
      <section class="records quote-record-table">
        <header><span>报价单 / 商品</span><span>客户</span><span>报价规模</span><span>状态 / 操作</span></header>
        <article v-for="row in list" :key="row.id">
          <div class="quote-info"><img v-if="recordProductImage(row)" :src="recordProductImage(row)" :alt="row.productSummary"><i v-else class="quote-image-placeholder">{{ row.productSummary.slice(0,1)||'商' }}</i><span class="quote-info-copy"><b>{{ row.no }}</b><strong>{{ row.productSummary }}</strong><small>{{ row.primarySku }} · {{ row.quoteMode==='bundle' ? '组合报价' : '单品SKU' }}<template v-if="!isMine"> · {{ row.salespersonName }}</template></small></span></div>
          <div><b>{{ row.customerName }}</b><small>创建于 {{ dateTime(row.createdAt) }}</small></div>
          <div class="route-summary"><b>{{ hasMultipleOptions(row) ? '多方案报价' : '单方案报价' }}</b><span class="country-tags"><i>{{ recordCountries(row).length || 1 }}国</i><i>{{ recordOptions(row).length || 1 }}渠道</i><em v-for="country in recordCountries(row).slice(0,2)" :key="country">{{ country }}</em><em v-if="recordCountries(row).length>2">+{{ recordCountries(row).length-2 }}</em></span></div>
          <div class="record-row-actions"><em :class="row.status">{{ statusText(row.status) }}</em><button class="view-record" @click="open(row)">查看报价单</button></div>
        </article>
        <div v-if="!list.length" class="empty"><b>暂无报价记录</b><span>{{ isMine ? '填写客户名称并保存报价后，记录会自动显示在这里。' : '暂时没有业务员保存报价记录。' }}</span><RouterLink v-if="isMine" to="/quotation">去新建报价</RouterLink></div>
      </section>
    </main>
    <div v-if="selected" class="mask" @click.self="closeDrawer">
      <aside class="record-drawer">
        <header><div><small>{{ editing ? 'QUOTATION FOLLOW-UP' : 'QUOTATION DOCUMENT' }}</small><h2>{{ editing ? (selected.status === 'pending' ? '回填成交结果' : '修改成交结果') : selected.no }}</h2><span v-if="!editing">{{ selected.customerName }} · {{ selected.productSummary }} · {{ recordCountries(selected).length || 1 }}国{{ recordOptions(selected).length || 1 }}渠道</span></div><button aria-label="关闭" @click="closeDrawer">×</button></header>

        <template v-if="!editing">
          <nav class="detail-tabs drawer-tabs"><button :class="{active:detailTab==='overview'}" @click="detailTab='overview'">报价概览</button><button :class="{active:detailTab==='options'}" @click="detailTab='options'">国家与渠道 <i>{{ recordOptions(selected).length }}</i></button><button :class="{active:detailTab==='history'}" @click="detailTab='history'">修改记录 <i>{{ revisionGroups.length }}</i></button></nav>
          <section v-if="detailTab==='overview'" class="overview-panel">
            <div class="overview-metrics"><article><small>报价国家</small><b>{{ recordCountries(selected).length || 1 }}</b><span>个国家</span></article><article><small>报价渠道</small><b>{{ recordOptions(selected).length || 1 }}</b><span>条渠道</span></article><article><small>1件报价区间</small><b>{{ hasMultipleOptions(selected) ? quote1UsdRange(selected) : usd(selected.systemQuoteUsd) }}</b><span>{{ hasMultipleOptions(selected) ? quote1CnyRange(selected) : cny(selected.systemQuoteCny) }}</span></article></div>
            <article class="primary-plan"><header><b>首选方案</b><span>报价单优先展示</span></header><div><span><strong>{{ primaryOption(selected)?.country || selected.country }} · {{ primaryOption(selected)?.channel || selected.channel }}</strong><small>{{ primaryOption(selected)?.carrier || selected.carrier }} · {{ primaryOption(selected)?.eta || selected.rule }}</small></span><b>{{ optionPrice(primaryOption(selected)?.quote1Usd ?? selected.systemQuoteUsd) }}</b></div></article>
            <section class="overview-info"><header>报价基本信息</header><div><span>客户</span><b>{{ selected.customerName }}</b><span>商品</span><b>{{ selected.productSummary }}</b><span>SKU</span><b>{{ selected.primarySku }}</b><span>报价模式</span><b>{{ selected.matrixMode === 'template' ? `模板 · ${selected.quotationTemplateName || '个人报价'}` : hasMultipleOptions(selected) ? '多国家多渠道报价' : '常用国家快速报价' }}</b><span>客户等级</span><b>{{ selected.customerGrade }}</b><span>自定义数量</span><b>{{ selected.customQuoteQuantity || '—' }}{{ selected.quoteMode==='bundle'?'套':'件' }}</b><span>创建时间</span><b>{{ dateTime(selected.createdAt) }}</b><span>最后修改</span><b>{{ dateTime(selected.updatedAt) }}</b></div></section>
            <section class="outcome-card"><header><b>客户成交结果</b></header><div><em :class="selected.status">{{ statusText(selected.status) }}</em><span v-if="selected.dealLines?.length">成交渠道 <b>{{ selected.dealLines.length }}条</b></span><span v-if="selected.dealQuantity">成交总数量 <b>{{ selected.dealQuantity }}{{ selected.quoteMode==='bundle'?'套':'件' }}</b></span><span v-if="selected.actualQuoteUsd">成交总金额 <b>{{ usd(selected.actualQuoteUsd) }}</b></span><span v-if="selected.status==='pending'">等待业务员回填客户成交结果</span></div><div v-if="selected.dealLines?.length" class="saved-deal-lines"><article v-for="line in selected.dealLines" :key="line.id"><span><b>{{ line.optionLabel }}</b><small>{{ usd(line.unitPriceUsd) }} × {{ line.quantity }}{{ selected.quoteMode==='bundle'?'套':'件' }}</small></span><strong>{{ usd(line.amountUsd) }}</strong></article></div></section>
            <button class="view-options" @click="detailTab='options'">查看全部国家与渠道报价 →</button>
          </section>
          <section v-else-if="detailTab==='options'" class="option-detail-panel"><header><div><b>国家与渠道报价明细</b><span>按国家分组查看本次保存的全部方案</span></div><em>{{ selectedOptionGroups.length }} 国 · {{ recordOptions(selected).length }} 渠道</em></header><div class="detail-country-groups"><details v-for="(group,index) in selectedOptionGroups" :key="group.country" :open="index===0 || group.options.some(option=>option.isPrimary || selectedDealOptionIds.has(option.id))"><summary><span><b>{{ group.countryCode || '' }} {{ group.country }}</b><small>{{ group.options.length }} 条渠道</small></span><i>展开⌄</i></summary><div class="detail-option-head"><span>渠道 / 服务商</span><span>时效</span><span>1件</span><span>2件</span><span>3件</span><span>{{ selected.customQuoteQuantity || '自定义' }}件</span></div><article v-for="option in group.options" :key="option.id" :class="{primary:option.isPrimary,deal:selectedDealOptionIds.has(option.id)}"><span><b>{{ option.channel }}</b><small>{{ option.carrier }} · {{ option.rule }}</small><em v-if="option.isPrimary">首选</em><em v-if="selectedDealOptionIds.has(option.id)" class="deal-badge">已成交</em></span><b>{{ option.eta }}</b><i>{{ optionPrice(option.quote1Usd) }}</i><i>{{ optionPrice(option.quote2Usd) }}</i><i>{{ optionPrice(option.quote3Usd) }}</i><i>{{ optionPrice(option.quoteCustomUsd) }}</i></article></details></div></section>
          <section v-else class="revision-history detail-history"><header><b>处理 / 修改记录</b><span>{{ revisionGroups.length }} 次操作</span></header><div v-if="revisionGroups.length"><article v-for="group in revisionGroups" :key="group.id"><time>{{ dateTime(group.changedAt) }}</time><span>{{ group.editorName }} · {{ group.editorAccount }}</span><p v-for="revision in group.changes" :key="revision.id"><b>{{ revision.fieldLabel }}</b>：{{ revision.before || '未填写' }} → {{ revision.after || '未填写' }}</p></article></div><p v-else class="history-empty">暂无可追溯的修改记录；旧记录将从下一次修改开始记录。</p></section>
          <footer class="drawer-view-footer"><button @click="closeDrawer">关闭</button><button v-if="isMine" class="primary" @click="processRecord(selected)">{{ selected.status==='pending' ? '去处理成交结果' : '编辑成交结果' }}</button></footer>
        </template>

        <template v-else>
          <section class="snapshot"><span>报价单号</span><b>{{ selected.no }}</b><span>客户</span><b>{{ selected.customerName }}</b><span>{{ hasMultipleOptions(selected) ? '1件报价区间' : '系统报价' }}</span><b>{{ hasMultipleOptions(selected) ? `${quote1UsdRange(selected)} / ${quote1CnyRange(selected)}` : `${usd(selected.systemQuoteUsd)} / ${cny(selected.systemQuoteCny)}` }}</b><span>首选报价渠道</span><b>{{ selected.country }} · {{ selected.channel }}</b><span>创建时间</span><b>{{ dateTime(selected.createdAt) }}</b><span>最后修改</span><b>{{ dateTime(selected.updatedAt) }}</b></section>
          <section v-if="recordOptions(selected).length" class="specified-snapshot"><header><b>{{ selected.matrixMode === 'template' ? '模板报价清单' : hasMultipleOptions(selected) ? '多国家渠道报价清单' : '报价方案' }}</b><span>{{ selectedOptionGroups.length }} 个国家 · {{ recordOptions(selected).length }} 条渠道</span></header><div class="option-table-head"><span>渠道 / 服务商</span><span>预计时效</span><span>1件</span><span>2件</span><span>3件</span><span>{{ selected.customQuoteQuantity || '自定义' }}件</span></div><div class="country-option-groups"><details v-for="(group,index) in selectedOptionGroups" :key="group.country" :open="index===0 || group.options.some(option=>option.isPrimary || selectedDealOptionIds.has(option.id))"><summary><span><b>{{ group.countryCode || '' }} {{ group.country }}</b><small>{{ group.options.length }} 条渠道</small></span><i>⌄</i></summary><article v-for="option in group.options" :key="option.id" :class="{ primary:option.isPrimary, deal:selectedDealOptionIds.has(option.id) }"><span><b>{{ option.channel }}</b><small>{{ option.carrier }} · {{ option.rule }}<template v-if="option.quoteRegion"> · {{ option.quoteRegion }}</template></small><em v-if="option.isPrimary">首选</em><em v-if="selectedDealOptionIds.has(option.id)" class="deal-badge">已成交</em></span><b>{{ option.eta }}</b><em>{{ optionPrice(option.quote1Usd) }}</em><em>{{ optionPrice(option.quote2Usd) }}</em><em>{{ optionPrice(option.quote3Usd) }}</em><em class="custom-option-price">{{ optionPrice(option.quoteCustomUsd) }}</em></article></details></div></section>
